// Gets the binding power of an operator.
int nc_precedence(NcToken t) {
    if (nc_is(t, "||")) {
        return 1;
    }
    if (nc_is(t, "&&")) {
        return 2;
    }
    if (nc_is(t, "==") || nc_is(t, "!=")) {
        return 3;
    }
    if (nc_is(t, "<") || nc_is(t, "<=") || nc_is(t, ">") || nc_is(t, ">=")) {
        return 4;
    }
    if (nc_is(t, "+") || nc_is(t, "-")) {
        return 5;
    }
    if (nc_is(t, "*") || nc_is(t, "/") || nc_is(t, "%")) {
        return 6;
    }
    return -1;
}

